    async def purge_cdn_cache(
        self,
        distribution_id: str,
        *,
        mode: PurgeCdnCacheRequestMode,
        workspace_id: typing.Optional[str] = None,
        paths: typing.Optional[typing.Sequence[str]] = OMIT,
        hostnames: typing.Optional[typing.Sequence[str]] = OMIT,
        tags: typing.Optional[typing.Sequence[str]] = OMIT,
        prefixes: typing.Optional[typing.Sequence[str]] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CdnCachePurge:
        """
        Purges matching cache content synchronously for a distribution in the
        selected workspace. For a normal single-page application deployment,
        use `mode: url` with `paths: ["/index.html"]`. Do not purge
        fingerprinted assets such as `/assets/app.a91c3.js`; use `paths:
        ["/*"]` only for an emergency full-cache invalidation.

        Parameters
        ----------
        distribution_id : str
            CDN distribution ID.

        mode : PurgeCdnCacheRequestMode
            - `url`: purge the paths in `paths`.
            - `hostname`: purge everything for the hostnames in `hostnames`.
            - `tag`: purge content tagged with `tags`.
            - `prefix`: purge paths starting with `prefixes`.
            - `all`: purge the whole distribution.

        workspace_id : typing.Optional[str]
            The positive numeric workspace ID to scope this request to. Zero, negative, and non-numeric values are rejected.

        paths : typing.Optional[typing.Sequence[str]]
            Paths to purge, for `url` mode.

        hostnames : typing.Optional[typing.Sequence[str]]
            Hostnames to purge, for `hostname` mode.

        tags : typing.Optional[typing.Sequence[str]]
            Cache tags to purge, for `tag` mode.

        prefixes : typing.Optional[typing.Sequence[str]]
            Path prefixes to purge, for `prefix` mode.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CdnCachePurge
            Cache purge completed.

        Examples
        --------
        import asyncio

        from ibee import AsyncIbee

        client = AsyncIbee(
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            await client.cdn.purge_cdn_cache(
                distribution_id="distribution_id",
                workspace_id="710995",
                mode="url",
                paths=["/index.html"],
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.purge_cdn_cache(
            distribution_id,
            mode=mode,
            workspace_id=workspace_id,
            paths=paths,
            hostnames=hostnames,
            tags=tags,
            prefixes=prefixes,
            request_options=request_options,
        )
        return _response.data
